from collections import defaultdict
import sys

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_optimal_paths(n, edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)

    for u in range(1, n + 1):
        for v in adj_list[u]:
            for w in adj_list[v]:
                if u != w and v != w and u != v:
                    if find(parent, u) != find(parent, w):
                        union(parent, rank, u, w)

    count = 0
    visited = set()
    for u in range(1, n + 1):
        if u not in visited:
            component_size = 0
            stack = [u]
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    component_size += 1
                    stack.extend(adj_list[node])
            count += component_size * (component_size - 1) // 2

    return count

